// /api/roi-analysis — Vercel serverless function (Node.js runtime).
//
// Enriches the AI ROI calculator's deterministic result with a short,
// grounded narrative (diagnosis, priorities, risks, confidence note)
// generated by an LLM via OpenRouter. The model is NEVER allowed to
// invent numbers — it only reasons over the figures we send it.
//
// Cost model: OpenRouter free-tier models only, tried in order with
// automatic fallback on rate-limit/failure. Never touches a paid model,
// so this endpoint can never generate a bill.

// Free-tier models only, tried in this order. Picked empirically: these
// three reliably return clean JSON without burning the token budget on
// hidden reasoning traces or routing to unrelated (e.g. safety-classifier)
// models the way OpenRouter's generic "openrouter/free" auto-router did
// in testing. Re-validate this list occasionally — OpenRouter's free
// catalog changes over time.
const MODELS = [
  'minimax/minimax-m3:free',
  'minimax/minimax-m2.7:free',
  'z-ai/glm-5.2:free'
];

const SYSTEM_PROMPT = `You are a careful business analyst writing a short enrichment note for an AI-adoption ROI report.

Hard rules:
- Use ONLY the numbers given to you in the user message. Never invent statistics, benchmarks, company names, sources, or citations that were not provided.
- Do not restate every number verbatim in prose form; synthesize and prioritize instead.
- Be specific to the given industry, company size and top impact area. Avoid generic filler that could apply to any company.
- The "investment level" you are given describes a SPECIFIC implementation depth (e.g. self-serve subscriptions with no integration, or a coordinated internal rollout, or a full process redesign with dedicated specialists). Your diagnosis MUST reflect that this ROI assumes that specific depth of work, not "just buying AI subscriptions", and must explain, in plain terms, what kind of effort actually has to happen for these numbers to be real.
- Keep total output concise: diagnosis under 90 words, each priority "why" under 30 words, each risk under 25 words, confidence note under 40 words, verdict summary under 45 words.
- Never use an em dash (—) anywhere in your output. Use a comma, a period, or a new sentence instead.
- Output ONLY valid JSON. No markdown code fences, no commentary before or after.

Required JSON shape:
{
  "diagnosis": string,
  "priorities": [ { "title": string, "why": string } ]  // exactly 3 items, ordered by impact
  "risks": [ string ]  // exactly 3 items
  "confidence_note": string  // one sentence on why the numbers do or don't hang together, referencing only the given figures
  "verdict": {
    "recommendation": string,  // exactly one of: "Proceed", "Pilot first", "Hold off"
    "pros": [ string ],   // exactly 2 items, concrete advantages specific to this case
    "cons": [ string ],   // exactly 2 items, concrete disadvantages/caveats specific to this case
    "summary": string     // one closing sentence: should they do this and why, in plain language
  }
}`;

function buildUserPrompt(input) {
  const cur = input.currency === 'USD' ? '$' : '€';
  return [
    `Industry: ${input.industry}`,
    `Company size: ${input.companySize}`,
    `Investment level: ${input.investmentLevel}, "${input.investmentTagline || ''}"`,
    `What this investment level actually involves: ${input.investmentDescription || 'not provided'}`,
    `Assumed adoption rate: ${input.adoptionPct}% of affected staff actually using the tools`,
    `Tooling/license cost: ${cur}${input.toolCostPerUserYear} per user per year`,
    `Implementation services scale factor: x${input.servicesFactor} (relative to a baseline services cost)`,
    `12-month ROI: ${input.roiPct}%`,
    `Annual savings: ${cur}${input.annualSavings}`,
    `Year-1 investment: ${cur}${input.year1Cost}`,
    `Automatable hours per year: ${input.automatableHours}`,
    `Payback period: ${input.paybackMonths !== null ? input.paybackMonths + ' months' : 'not reached in year 1'}`,
    `Share of employees affected by repetitive work: ${input.affectedPct}%`,
    `FTE capacity unlocked: ${input.fte}`,
    `Top impact area: ${input.topImpactArea}`,
    `Opportunity level: ${input.opportunityLevel}`,
    ``,
    `Write the JSON now.`
  ].join('\n');
}

function safeParseJSON(raw) {
  if (!raw) return null;
  // Strip markdown code fences if the model added them despite instructions.
  const cleaned = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    // Try to recover a JSON object embedded in extra text.
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch { return null; }
    }
    return null;
  }
}

function stripEmDash(value) {
  if (typeof value === 'string') return value.replace(/\s*—\s*/g, ', ').replace(/,\s*,/g, ',');
  if (Array.isArray(value)) return value.map(stripEmDash);
  if (value && typeof value === 'object') {
    const out = {};
    for (const k in value) out[k] = stripEmDash(value[k]);
    return out;
  }
  return value;
}

function isValidShape(a) {
  return a &&
    typeof a.diagnosis === 'string' && a.diagnosis.length > 0 &&
    Array.isArray(a.priorities) &&
    a.priorities.every(p => p && typeof p.title === 'string' && typeof p.why === 'string') &&
    Array.isArray(a.risks) &&
    a.risks.every(r => typeof r === 'string') &&
    typeof a.confidence_note === 'string' &&
    a.verdict && typeof a.verdict === 'object' &&
    typeof a.verdict.recommendation === 'string' &&
    Array.isArray(a.verdict.pros) && a.verdict.pros.every(x => typeof x === 'string') &&
    Array.isArray(a.verdict.cons) && a.verdict.cons.every(x => typeof x === 'string') &&
    typeof a.verdict.summary === 'string';
}

function validateInput(body) {
  if (!body || typeof body !== 'object') return false;
  if (typeof body.roiPct !== 'number') return false;
  if (typeof body.industry !== 'string' || body.industry.length > 80) return false;
  if (typeof body.companySize !== 'string' || body.companySize.length > 40) return false;
  if (typeof body.topImpactArea !== 'string' || body.topImpactArea.length > 120) return false;
  return true;
}

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    res.status(405).json({ ok: false, reason: 'method_not_allowed' });
    return;
  }

  const apiKey = process.env.OPENROUTER_API_KEY;
  if (!apiKey) {
    // Server not configured yet — fail soft, frontend falls back locally.
    res.status(200).json({ ok: false, reason: 'not_configured' });
    return;
  }

  const input = req.body;
  if (!validateInput(input)) {
    res.status(400).json({ ok: false, reason: 'invalid_input' });
    return;
  }

  const userPrompt = buildUserPrompt(input);
  const site = process.env.PUBLIC_SITE_URL || 'https://humanetheory.ai';

  // Free-tier OpenRouter models can take 10-20s+ to respond under load, so
  // trying them one after another with a short per-model timeout starves
  // every attempt. Race them in parallel instead: first valid response wins.
  async function callModel(model) {
    const controller = new AbortController();
    const perModelTimeout = setTimeout(() => controller.abort(), 25000);
    try {
      const upstream = await fetch('https://openrouter.ai/api/v1/chat/completions', {
        method: 'POST',
        signal: controller.signal,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
          'HTTP-Referer': site,
          'X-Title': 'Humane Theory — AI ROI'
        },
        body: JSON.stringify({
          model,
          messages: [
            { role: 'system', content: SYSTEM_PROMPT },
            { role: 'user', content: userPrompt }
          ],
          max_tokens: 1700,
          temperature: 0.4,
          response_format: { type: 'json_object' }
        })
      });
      if (upstream.status === 429 || upstream.status >= 500 || !upstream.ok) return null;

      const data = await upstream.json();
      const raw = data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
      const parsed = safeParseJSON(raw);
      if (!parsed || !isValidShape(parsed)) return null;

      return { model, analysis: stripEmDash(parsed) };
    } catch {
      return null;
    } finally {
      clearTimeout(perModelTimeout);
    }
  }

  const results = await Promise.allSettled(MODELS.map(callModel));
  const win = results.find(r => r.status === 'fulfilled' && r.value);
  if (win) {
    res.status(200).json({ ok: true, model: win.value.model, analysis: win.value.analysis });
    return;
  }

  // Every free model failed or was rate-limited: tell the frontend to
  // fall back to its own locally-generated summary. Never an error page.
  res.status(200).json({ ok: false, reason: 'unavailable' });
}
